<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    python3-jinja2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libegl1-mesa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libsdl1.2-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pylint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xterm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
